65	                .map_err(|e| fail(format!("bindings[{index}]: {e}")))?;
66	            binding
67	                .action
68	                .validate()
69	                .map_err(|e| fail(format!("bindings[{index}].action: {e}")))?;
70	            let (key_bytes, modifier_names, symbol_name, code) = match &binding.key {
71	                Key::Sym { sym } => {
72	                    let mut parts = sym.split('+').collect::<Vec<_>>();
73	                    let name = parts.pop().expect("validated nonempty chord");
74	                    (sym.len(), parts, Some(name), None)
75	                }
