77	                    modifiers.iter().map(String::len).sum(),
78	                    modifiers.iter().map(String::as_str).collect(),
79	                    None,
80	                    Some(*code),
81	                ),
82	            };
83	            bytes = bytes
84	                .checked_add(key_bytes)
85	                .ok_or_else(|| fail("binding string budget exceeded".into()))?;
86	            if let Action::Spawn { argv } = &binding.action {
87	                for arg in argv {
88	                    bytes = bytes
89	                        .checked_add(arg.len())
90	                        .ok_or_else(|| fail("binding string budget exceeded".into()))?;
91	                }
92	            }
93	            if bytes > MAX_STRING_BYTES {
94	                return Err(fail("binding strings exceed 4 MiB".into()));
95	            }
96	            let mut modifiers = Modifiers::default();
97	            for name in modifier_names {
98	                match name {
99	                    "Ctrl" => modifiers.ctrl = true,
100	                    "Alt" => modifiers.alt = true,
101	                    "Shift" => modifiers.shift = true,
102	                    "Super" | "Logo" => modifiers.logo = true,
103	                    _ => unreachable!("schema normalization already checked modifier tokens"),
104	                }
105	            }
106	            let previous = if let Some(name) = symbol_name {
107	                let sym = xkb::keysym_from_name(name, xkb::KEYSYM_NO_FLAGS);
108	                if sym == xkb::Keysym::NoSymbol {
109	                    return Err(fail(format!(
110	                        "bindings[{index}]: unknown case-sensitive keysym {name}"
111	                    )));
112	                }
113	                result.symbols.insert((sym.raw(), modifiers), index)
114	            } else {
115	                result
116	                    .codes
117	                    .insert((code.expect("validated code binding"), modifiers), index)
118	            };
119	            if let Some(previous) = previous {
120	                return Err(fail(format!(
121	                    "bindings[{index}] conflicts with bindings[{previous}] after keysym/modifier resolution"
122	                )));
123	            }
124	            result.actions.push(binding.action.clone());
125	        }
126	
127	        let mut keys = Vec::new();
128	        keymap.key_for_each(|_, code| {
129	            if keys.len() <= MAX_KEYCODES {
130	                keys.push(code);
131	            }
132	        });
133	        if keys.len() > MAX_KEYCODES {
134	            return Err(fail("keymap exceeds 4096-key validation budget".into()));
135	        }
136	        // Physical evdev bindings do not require a symbol in this keymap. A
137	        // custom keyboard may report a valid code with no XKB assignment.
138	        let mut reached: BTreeSet<_> = result.codes.values().copied().collect();
139	        let mut resolved = 0usize;
140	        let chord_modifiers: BTreeSet<_> = result
141	            .codes
142	            .keys()
143	            .map(|(_, m)| *m)
144	            .chain(result.symbols.keys().map(|(_, m)| *m))
145	            .collect();
146	        for key in keys {
147	            let Some(code) = key.raw().checked_sub(8).and_then(|c| u16::try_from(c).ok()) else {
148	                continue;
149	            };
150	            if !(1..=767).contains(&code) {
151	                continue;
152	            }
153	            let layouts = keymap.num_layouts_for_key(key);
154	            if layouts > MAX_LAYOUTS_PER_KEY {
155	                return Err(fail("keymap exceeds 32 layouts per key".into()));
156	            }
157	            for layout in 0..layouts {
158	                let symbols = keymap.key_get_syms_by_level(key, layout, 0);
159	                for modifiers in &chord_modifiers {
160	                    let mut owner = result.codes.get(&(code, *modifiers)).copied();
161	                    for symbol in symbols {
162	                        if let Some(&index) = result.symbols.get(&(symbol.raw(), *modifiers)) {
163	                            if let Some(previous) = owner
164	                                && previous != index
165	                            {
166	                                return Err(fail(format!(
167	                                    "bindings[{index}] and bindings[{previous}] both match evdev {code} in layout {layout}"
168	                                )));
169	                            }
170	                            owner = Some(index);
171	                        }
172	                    }
173	                    if let Some(index) = owner {
174	                        reached.insert(index);
175	                        resolved += 1;
176	                        if resolved > MAX_RESOLVED_CHORDS {
177	                            return Err(fail(
178	                                "binding expansion exceeds 65536 resolved chords".into(),
179	                            ));
180	                        }
181	                    }
182	                }
183	            }
184	        }
185	        result.inactive = (0..bindings.len())
186	            .filter(|index| !reached.contains(index))
187	            .collect();
188	        if unmapped == UnmappedPolicy::Reject && !result.inactive.is_empty() {
189	            return Err(fail(format!(
190	                "bindings[{}]: chord is absent from the keymap's base levels",
191	                result.inactive[0]
192	            )));
193	        }
194	        result.symbols.retain(|_, index| reached.contains(index));
195	        Ok(result)
196	    }
197	
198	    pub fn inactive_indices(&self) -> &[usize] {
199	        &self.inactive
200	    }
201	
202	    pub fn len(&self) -> usize {
203	        self.actions.len()
204	    }
205	    pub fn is_empty(&self) -> bool {
206	        self.actions.is_empty()
207	    }
208	
209	    /// Input code is evdev, not XKB (which adds 8). Base symbols must come from
210	    /// the current group of the same keymap used for compilation. Ignore locked
211	    /// Caps/Num state; caller passes exact Ctrl/Alt/Shift/Super and level shifts.
212	    pub fn action(
213	        &self,
214	        code: u16,
215	        base_symbols: &[xkb::Keysym],
216	        modifiers: Modifiers,
217	    ) -> Option<&Action> {
218	        if !(1..=767).contains(&code) || modifiers.level3 || modifiers.level5 {
219	            return None;
220	        }
221	        let mut owner = self.codes.get(&(code, modifiers)).copied();
222	        for symbol in base_symbols {
223	            if let Some(&index) = self.symbols.get(&(symbol.raw(), modifiers)) {
224	                if let Some(previous) = owner
225	                    && previous != index
226	                {
227	                    return None;
228	                }
229	                owner = Some(index);
230	            }
231	        }
232	        owner.map(|index| &self.actions[index])
233	    }
234	}
