1	//! Worker-owned evaluation of already-acquired source snapshots.
2	use crate::{CompiledConfig, ConfigError, HelperLimits, MAX_SOURCE_BYTES};
3	use std::{
4	    path::PathBuf,
5	    sync::{
6	        Arc, Condvar, Mutex, Weak,
7	        atomic::{AtomicBool, Ordering},
8	    },
9	    thread::{self, JoinHandle},
10	};
11	
12	/// Checked, coordinator-local request identity. Zero is never issued.
13	#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
14	pub struct ConfigGeneration(u64);
15	impl ConfigGeneration {
16	    pub fn get(self) -> u64 {
17	        self.0
18	    }
19	}
20	
21	#[derive(Debug, thiserror::Error, PartialEq, Eq)]
22	pub enum ConfigRequestError {
23	    #[error("configuration coordinator is shut down")]
24	    Closed,
25	    #[error("configuration worker stopped unexpectedly")]
26	    WorkerStopped,
27	    #[error("configuration request generation exhausted")]
28	    GenerationExhausted,
29	    #[error("configuration source exceeds 1 MiB")]
30	    SourceTooLarge,
31	    #[error("configuration source is not UTF-8")]
32	    SourceNotUtf8,
33	}
34	#[derive(Debug, thiserror::Error, PartialEq, Eq)]
35	pub enum ConfigCommitError {
36	    #[error("configuration coordinator is shut down")]
37	    Closed,
38	    #[error("configuration candidate belongs to another coordinator")]
39	    ForeignCandidate,
40	    #[error("configuration candidate has been superseded")]
41	    Stale,
42	}
43	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
44	pub enum ConfigFailureKind {
45	    Invalid,
46	    Io,
47	    Timeout,
48	    Helper,
49	    Cancelled,
50	}
51	/// One bounded diagnostic. No source snapshot or diagnostic history is retained.
52	#[derive(Debug)]
53	pub struct ConfigEvaluationFailure {
54	    pub kind: ConfigFailureKind,
55	    pub diagnostic: String,
56	}
57	impl From<ConfigError> for ConfigEvaluationFailure {
58	    fn from(error: ConfigError) -> Self {
59	        let kind = match &error {
60	            ConfigError::Invalid(_) => ConfigFailureKind::Invalid,
61	            ConfigError::Io(_) => ConfigFailureKind::Io,
62	            ConfigError::Timeout => ConfigFailureKind::Timeout,
63	            ConfigError::Helper { .. } => ConfigFailureKind::Helper,
64	            ConfigError::Cancelled => ConfigFailureKind::Cancelled,
65	        };
66	        // Helper errors, regex diagnostics and serde errors may quote arbitrary
67	        // source-controlled text. Retain only static stage/class information;
68	        // the synchronous API remains available to explicit diagnostic tooling.
69	        let diagnostic = match kind {
70	            ConfigFailureKind::Invalid => "configuration result failed schema or value validation",
71	            ConfigFailureKind::Io => "configuration helper could not be started or supervised",
72	            ConfigFailureKind::Timeout => "configuration helper exceeded its evaluation deadline",
73	            ConfigFailureKind::Helper => {
74	                "configuration helper rejected evaluation or exited unsuccessfully"
75	            }
76	            ConfigFailureKind::Cancelled => "configuration evaluation was cancelled",
77	        }
78	        .to_owned();
79	        Self { kind, diagnostic }
80	    }
81	}
82	/// An evaluated value, not an applied configuration. Intentionally not Clone.
83	#[derive(Debug)]
84	pub struct ConfigCandidate {
85	    generation: ConfigGeneration,
86	    owner: Weak<Shared>,
87	    config: Arc<CompiledConfig>,
88	}
89	impl ConfigCandidate {
90	    pub fn generation(&self) -> ConfigGeneration {
91	        self.generation
92	    }
93	    pub fn config(&self) -> &CompiledConfig {
94	        &self.config
95	    }
96	}
97	#[derive(Debug)]
98	pub struct ConfigEvaluation {
99	    pub generation: ConfigGeneration,
100	    pub result: Result<ConfigCandidate, ConfigEvaluationFailure>,
101	}
102	#[derive(Debug, Clone, Copy)]
103	pub struct ConfigCoordinatorStatus {
104	    pub latest: Option<ConfigGeneration>,
105	    pub active: Option<ConfigGeneration>,
106	    pub pending: Option<ConfigGeneration>,
107	    /// Observation only; signalling uses the supervisor's unreaped Child handle.
108	    pub active_helper_pid: Option<u32>,
109	    pub completion_ready: bool,
110	    pub closed: bool,
111	}
112	#[derive(Debug)]
113	struct Job {
114	    generation: ConfigGeneration,
115	    source: Vec<u8>,
116	}
117	#[derive(Debug, Default)]
118	struct State {
119	    latest: u64,
120	    active: Option<ConfigGeneration>,
121	    active_helper_pid: Option<u32>,
122	    pending: Option<Job>,
123	    completion: Option<ConfigEvaluation>,
124	    closed: bool,
125	}
126	#[derive(Debug, Default)]
127	struct Shared {
128	    state: Mutex<State>,
129	    changed: Condvar,
130	    cancelled: AtomicBool,
131	}
132	
133	/// One worker, one active evaluation, one replaceable pending source, and one
134	/// completion slot. All public mutation needs exclusive caller ownership.
135	///
136	/// `notify` runs on the worker, outside the mutex, and must be nonblocking and
137	/// nonpanicking (for example a coalesced event-loop ping). Notifications are hints:
138	/// stale work may already have been superseded before the caller handles a wake.
139	/// This crate does not read source files or depend on any event-loop implementation.
140	/// Call shutdown/Drop outside compositor dispatch: joining, exec and kill/wait have
141	/// no universal wall-clock bound under kernel/filesystem failure.
142	pub struct ConfigCoordinator {
143	    shared: Arc<Shared>,
144	    worker: Option<JoinHandle<()>>,
145	    last_good: Option<Arc<CompiledConfig>>,
146	}
147	impl ConfigCoordinator {
148	    pub fn new(
149	        helper: PathBuf,
150	        limits: HelperLimits,
151	        notify: impl Fn() + Send + 'static,
152	    ) -> std::io::Result<Self> {
153	        let shared = Arc::new(Shared::default());
154	        let worker_shared = shared.clone();
155	        let worker = thread::Builder::new()
156	            .name("flux-config".into())
157	            .spawn(move || {
158	                loop {
159	                    let job = {
160	                        let mut state = worker_shared
161	                            .state
162	                            .lock()
163	                            .unwrap_or_else(|e| e.into_inner());
164	                        while !state.closed && state.pending.is_none() {
165	                            state = worker_shared
166	                                .changed
167	                                .wait(state)
168	                                .unwrap_or_else(|e| e.into_inner());
169	                        }
170	                        if state.closed {
171	                            return;
172	                        }
173	                        let job = state.pending.take().expect("pending work after wait");
174	                        state.active = Some(job.generation);
175	                        job
176	                    };
177	                    let result = crate::supervisor::load_with_helper_cancellable(
178	                        &helper,
179	                        &job.source,
180	                        limits,
181	                        &worker_shared.cancelled,
182	                        |pid| {
183	                            let mut state = worker_shared
184	                                .state
185	                                .lock()
186	                                .unwrap_or_else(|e| e.into_inner());
187	                            state.active_helper_pid = Some(pid);
188	                        },
189	                    )
190	                    .map(|config| ConfigCandidate {
191	                        generation: job.generation,
192	                        owner: Arc::downgrade(&worker_shared),
193	                        config: Arc::new(config),
194	                    })
195	                    .map_err(ConfigEvaluationFailure::from);
196	                    let publish = {
197	                        let mut state = worker_shared
198	                            .state
