16	impl Fluxwm {
17	    /// Cancel the nested seat's held state when the host keyboard focus leaves.
18	    /// Logical window selection persists; no absent backend release is required.
19	    pub fn host_focus_changed(&mut self, focused: bool) {
20	        if self.host_focus == Some(focused) {
21	            return;
22	        }
23	        self.host_focus = Some(focused);
24	        self.bump_sequence();
25	        if focused {
26	            return;
27	        }
28	        self.stats.host_focus_losses += 1;
29	        let time = smithay::backend::input::InputTime::now();
30	        if let Some(keyboard) = self.seat.get_keyboard() {
31	            let mut keys: Vec<_> = keyboard.pressed_keys().into_iter().collect();
32	            keys.sort_by_key(|key| key.raw());
33	            self.stats.focus_cancelled_keys += keys.len() as u64;
34	            for code in keys {
35	                keyboard.input::<(), _>(
36	                    self,
37	                    code,
38	                    KeyState::Released,
39	                    SERIAL_COUNTER.next_serial(),
40	                    time,
41	                    |state, _, _| {
42	                        if state.suppressed_keys.remove(&code.raw()) {
43	                            FilterResult::Intercept(())
44	                        } else {
45	                            FilterResult::Forward
46	                        }
47	                    },
48	                );
49	            }
50	        }
51	        self.suppressed_keys.clear();
52	        let buttons: Vec<_> = self.pointer_presses.keys().copied().collect();
53	        self.stats.focus_cancelled_buttons += buttons.len() as u64;
54	        if let Some(pointer) = self.seat.get_pointer() {
55	            for button in buttons {
56	                pointer.button(
57	                    self,
58	                    &ButtonEvent {
59	                        button,
60	                        state: ButtonState::Released,
61	                        serial: SERIAL_COUNTER.next_serial(),
62	                        time,
63	                    },
64	                );
65	            }
66	            pointer.frame(self);
67	        }
68	        self.pointer_presses.clear();
69	        if let Some((_, grab)) = self.popup_grab.as_mut() {
70	            grab.ungrab(smithay::desktop::PopupUngrabStrategy::All);
71	        }
72	        self.cleanup_popup_grab();
73	        if let Some(pointer) = self.seat.get_pointer()
74	            && pointer.is_grabbed()
75	        {
76	            pointer.unset_grab(self, SERIAL_COUNTER.next_serial(), time);
77	        }
78	        self.pointer_focus_dirty = true;
79	    }
