81	    pub fn refresh_pointer_focus(&mut self) {
82	        if !self.pointer_focus_dirty {
83	            return;
84	        }
85	        let Some(pointer) = self.seat.get_pointer() else {
86	            return;
87	        };
88	        if pointer.is_grabbed() {
89	            // Keep the pending refresh until the grab ends. A composition while
90	            // an implicit click grab is active must not lose enter/leave repair.
91	            return;
92	        }
93	        self.pointer_focus_dirty = false;
94	        let location = pointer.current_location();
95	        let under = self.surface_under(location);
96	        if pointer.current_focus() == under.as_ref().map(|(surface, _)| surface.clone())
97	            && self.pointer_scene_target == under
98	        {
99	            return;
100	        }
101	        self.pointer_scene_target = under.clone();
102	        pointer.motion(
103	            self,
104	            under,
105	            &MotionEvent {
106	                location,
107	                serial: SERIAL_COUNTER.next_serial(),
108	                time: smithay::backend::input::InputTime::now(),
109	            },
110	        );
111	        pointer.frame(self);
112	    }
113	
114	    pub fn process_input_event<I: InputBackend>(&mut self, event: InputEvent<I>) {
115	        match event {
116	            InputEvent::Keyboard { event, .. } => {
117	                if self.host_focus == Some(false) {
118	                    return;
119	                }
120	                let serial = SERIAL_COUNTER.next_serial();
121	                let time = Event::time(&event);
122	
123	                let code = event.key_code();
124	                let pressed = event.state() == KeyState::Pressed;
125	                let Some(keyboard) = self.seat.get_keyboard() else {
126	                    return;
127	                };
128	                let action = keyboard
129	                    .input::<Option<flux_core::Action>, _>(
130	                        self,
131	                        code,
132	                        event.state(),
133	                        serial,
134	                        time,
135	                        |state, modifiers, handle| {
136	                            if !pressed {
137	                                return if state.suppressed_keys.remove(&code.raw()) {
138	                                    FilterResult::Intercept(None)
139	                                } else {
140	                                    FilterResult::Forward
141	                                };
142	                            }
143	                            if state.suppressed_keys.contains(&code.raw()) {
144	                                return FilterResult::Intercept(None);
145	                            }
146	                            // Smithay's actual backend/KeysymHandle code is XKB
147	                            // (+8), despite the backend trait's evdev wording.
148	                            let evdev = handle
149	                                .raw_code()
150	                                .raw()
151	                                .checked_sub(8)
152	                                .and_then(|code| u16::try_from(code).ok());
153	                            let action = evdev
154	                                .and_then(|code| {
155	                                    state.bindings.action(
156	                                        code,
157	                                        &handle.raw_syms(),
158	                                        flux_input::Modifiers {
159	                                            ctrl: modifiers.ctrl,
160	                                            alt: modifiers.alt,
161	                                            shift: modifiers.shift,
162	                                            logo: modifiers.logo,
163	                                            level3: modifiers.iso_level3_shift,
164	                                            level5: modifiers.iso_level5_shift,
165	                                        },
166	                                    )
167	                                })
168	                                .cloned();
169	                            if let Some(action) = action {
170	                                state.suppressed_keys.insert(code.raw());
171	                                FilterResult::Intercept(Some(action))
172	                            } else {
173	                                FilterResult::Forward
174	                            }
175	                        },
176	                    )
177	                    .flatten();
